from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session
from backend.services.db import connect
from backend.models import Goal, Insurance, Salary, Debt
from backend.schemas import GoalCreate, GoalUpdate, InsuranceCreate, InsuranceUpdate, SalaryCreate, SalaryUpdate, DebtCreate, DebtUpdate

router = APIRouter()

@router.post("/goals/", response_model=Goal)
def create_goal(goal: GoalCreate, db: Session = Depends(connect)):
    db_goal = Goal(**goal.dict())
    db.add(db_goal)
    db.commit()
    db.refresh(db_goal)
    return db_goal

@router.get("/goals/", response_model=list[Goal])
def read_goals(include_archived: bool = False, db: Session = Depends(connect)):
    query = db.query(Goal)
    if not include_archived:
        query = query.filter(Goal.archived_at.is_(None))
    return query.all()

@router.get("/goals/{goal_id}", response_model=Goal)
def read_goal(goal_id: int, db: Session = Depends(connect)):
    db_goal = db.query(Goal).filter(Goal.id == goal_id).first()
    if db_goal is None:
        raise HTTPException(status_code=404, detail="Goal not found")
    return db_goal

@router.put("/goals/{goal_id}", response_model=Goal)
def update_goal(goal_id: int, goal: GoalUpdate, db: Session = Depends(connect)):
    db_goal = db.query(Goal).filter(Goal.id == goal_id).first()
    if db_goal is None:
        raise HTTPException(status_code=404, detail="Goal not found")
    for key, value in goal.dict(exclude_unset=True).items():
        setattr(db_goal, key, value)
    db.commit()
    db.refresh(db_goal)
    return db_goal

@router.delete("/goals/{goal_id}", status_code=204)
def delete_goal(goal_id: int, db: Session = Depends(connect)):
    db_goal = db.query(Goal).filter(Goal.id == goal_id).first()
    if db_goal is None:
        raise HTTPException(status_code=404, detail="Goal not found")
    if db_goal.lots:
        raise HTTPException(status_code=409, detail="Cannot delete goal with lots")
    db.delete(db_goal)
    db.commit()

